mapper.select:
SELECT CAST(PG_CATALOG.ROW_TO_JSON(R) AS TEXT)
  FROM (
        SELECT ${projection}
          FROM ${target}
  ) R
 ORDER BY ${sort}
 OFFSET #{searchDto.offset} ROWS
 FETCH NEXT #{searchDto.size} ROWS ONLY

SELECT VERSION_NO
  FROM SCHED_TRANSFORM_RULE_VERSION
 WHERE TRANSFORM_RULE_VERSION_ID = #{transformRuleVersionId}

SELECT R.TRANSFORM_RESULT_ID, R.TRANSFORM_TASK_ID, T.RAW_DATA_ID, D.EXTERNAL_API_ID, A.API_NAME, V.TRANSFORM_RULE_ID, U.RULE_NAME, V.VERSION_NO, V.DATA_FORMAT, R.CREATED_AT, L.STATUS AS ANALYSIS_LOAD_STATUS FROM SCHED_TRANSFORM_RESULT R INNER JOIN SCHED_TRANSFORM_TASK T ON R.TRANSFORM_TASK_ID = T.TRANSFORM_TASK_ID INNER JOIN SCHED_COLLECT_RAW_DATA D ON T.RAW_DATA_ID = D.RAW_DATA_ID INNER JOIN SCHED_EXTERNAL_API A ON D.EXTERNAL_API_ID = A.EXTERNAL_API_ID INNER JOIN SCHED_TRANSFORM_RULE_VERSION V ON T.TRANSFORM_RULE_VERSION_ID = V.TRANSFORM_RULE_VERSION_ID INNER JOIN SCHED_TRANSFORM_RULE U ON V.TRANSFORM_RULE_ID = U.TRANSFORM_RULE_ID
LEFT JOIN SCHED_ANALYSIS_LOAD_SOURCE L ON L.ANALYSIS_MODEL_VERSION_ID = #{analysisModelVersionId} AND L.TRANSFORM_RESULT_ID = R.TRANSFORM_RESULT_ID WHERE V.TRANSFORM_RULE_ID = #{transformRuleId} AND T.STATUS = 'SUCCESS'
AND R.CREATED_AT >= #{startAt}
AND R.CREATED_AT < #{endAt}
AND T.TRANSFORM_RULE_VERSION_ID = #{transformRuleVersionId} AND NOT EXISTS ( SELECT 1 FROM SCHED_ANALYSIS_LOAD_SOURCE LS WHERE LS.ANALYSIS_MODEL_VERSION_ID = #{analysisModelVersionId} AND LS.RAW_DATA_ID = T.RAW_DATA_ID )
ORDER BY R.TRANSFORM_RESULT_ID DESC OFFSET #{searchDto.offset} ROWS FETCH NEXT #{searchDto.size} ROWS ONLY

SELECT COUNT(*)
  FROM SCHED_TRANSFORM_RESULT R
 INNER JOIN SCHED_TRANSFORM_TASK T
    ON R.TRANSFORM_TASK_ID = T.TRANSFORM_TASK_ID
 INNER JOIN SCHED_TRANSFORM_RULE_VERSION V
    ON T.TRANSFORM_RULE_VERSION_ID = V.TRANSFORM_RULE_VERSION_ID
 WHERE V.TRANSFORM_RULE_ID = #{transformRuleId}
   AND T.STATUS = 'SUCCESS'

   AND R.CREATED_AT  >=  #{startAt}


   AND R.CREATED_AT  <  #{endAt}


   AND T.TRANSFORM_RULE_VERSION_ID = #{transformRuleVersionId}
   AND NOT EXISTS (
       SELECT 1
         FROM SCHED_ANALYSIS_LOAD_SOURCE LS
        WHERE LS.ANALYSIS_MODEL_VERSION_ID = #{analysisModelVersionId}
          AND LS.RAW_DATA_ID = T.RAW_DATA_ID
   )

mapper.insert:
INSERT INTO PUBLIC.REAL_ESTATE_SALE_TRADE (
    ANALYSIS_LOAD_SOURCE_ID,
    SOURCE_ITEM_NO,

        ${field.column}

)
VALUES (
    #{analysisLoadSourceId},
    #{sourceItemNo},

        #{field.value}

)
